	"admindashboard/view/App.view.xml":'<mvc:View controllerName="admindashboard.controller.App"\n    displayBlock="true"\n    xmlns:mvc="sap.ui.core.mvc"\n    xmlns="sap.m"><App id="app"></App></mvc:View>',
	"admindashboard/view/Home.view.xml":'<mvc:View\n    controllerName="admindashboard.controller.Home"\n    xmlns:mvc="sap.ui.core.mvc"\n    xmlns="sap.m"><Page id="Paget" \n    title="IT Asset Lifecycle Management"><content><VBox id="Vboxt"\n                alignItems="Center"\n                justifyContent="Center"\n                class="sapUiLargeMargin"><Title id="Title"\n                    text="Asset Management Portal"/><Button id="B1"\n                    text="Admin Login"\n                    press=".onAdminPress"\n                    width="250px"\n                    class="sapUiSmallMargin"/><Button id="B2"\n                    text="Manager Login"\n                    press=".onManagerPress"\n                    width="250px"\n                    class="sapUiSmallMargin"/><Button id="B3"\n                    text="User"\n                    press=".onUserPress"\n                    width="250px"\n                    class="sapUiSmallMargin"/></VBox></content></Page></mvc:View>',
